set.seed(2026)
dir.create("data",FALSE);dir.create("output",FALSE);dir.create("figures",FALSE);dir.create("docs",FALSE)
n_org<-40;n_phys<-200;n<-6000
phys<-data.frame(physician_id=1:n_phys,org_id=sample(1:n_org,n_phys,TRUE),integrated=rbinom(n_phys,1,.45),prior_referral=rbinom(n_phys,1,.30),phys_re=rnorm(n_phys,0,.6))
org<-data.frame(org_id=1:n_org,specialist=rbinom(n_org,1,.35),org_re=rnorm(n_org,0,.35));phys<-merge(phys,org,by="org_id")
d<-data.frame(patient_id=1:n,physician_id=sample(1:n_phys,n,TRUE),age=round(runif(n,66,90),1),female=rbinom(n,1,.52),comorbidity=rpois(n,1.2),cancer=factor(sample(c("Breast","Colorectal","Lung","Pancreatic","Prostate"),n,TRUE)))
d<-merge(d,phys,by="physician_id",sort=FALSE);lp<-with(d,-2.8+.02*(age-75)+.09*comorbidity+.3*(cancer=="Pancreatic")+.2*integrated+.5*prior_referral+.2*specialist+phys_re+org_re);d$early_pc<-rbinom(n,1,plogis(lp));write.csv(d,"data/provider_patient_data.csv",row.names=FALSE)
base<-lm(early_pc~age+female+comorbidity+cancer,data=d);pf<-lm(early_pc~age+female+comorbidity+cancer+factor(physician_id),data=d);of<-lm(early_pc~age+female+comorbidity+cancer+factor(org_id),data=d)
metrics<-data.frame(metric=c("Overall early-PC billing rate","Residual variation explained by physician FE","Residual variation explained by organization FE"),estimate=c(mean(d$early_pc),1-var(resid(pf))/var(resid(base)),1-var(resid(of))/var(resid(base))));write.csv(metrics,"output/variation_metrics.csv",row.names=FALSE)
g<-glm(early_pc~age+female+comorbidity+cancer+integrated+prior_referral+specialist,family=binomial(),data=d);s<-coef(summary(g));assoc<-data.frame(term=rownames(s),odds_ratio=exp(s[,1]),lower=exp(s[,1]-1.96*s[,2]),upper=exp(s[,1]+1.96*s[,2]),p_value=s[,4],row.names=NULL);write.csv(assoc,"output/adjusted_associations.csv",row.names=FALSE)
pr<-aggregate(early_pc~physician_id,d,mean);pr<-pr[order(pr$early_pc),];png("figures/provider-variation.png",900,600);plot(seq_len(nrow(pr)),pr$early_pc,pch=16,col="#0072B2",xlab="Physicians ordered by observed rate",ylab="Early palliative-care billing rate",main="Variation Across Physicians");abline(h=mean(d$early_pc),lty=2);dev.off()
stopifnot(nrow(d)==n,all(metrics$estimate>=0),all(metrics$estimate<=1))
html<-sprintf('<!doctype html><meta charset="utf-8"><style>body{font:16px Arial;max-width:900px;margin:40px auto;color:#111;line-height:1.5}img{max-width:100%%}</style><h1>Provider Variation &amp; Fixed-Effects Analysis</h1><p><b>Question:</b> How much adjusted variation in early palliative-care billing is associated with physicians and organizations?</p><h2>Design</h2><p>Synthetic hierarchical cohort: %s patients, %s physicians, %s organizations.</p><h2>Findings</h2><p>Overall billing rate: %.1f%%. Descriptive residual variation reduction: physician FE %.1f%%; organization FE %.1f%%.</p><img src="../figures/provider-variation.png"><h2>Interpretation</h2><p>Fixed effects describe variation after measured case-mix adjustment; they do not establish causal provider performance.</p>',n,n_phys,n_org,100*metrics$estimate[1],100*metrics$estimate[2],100*metrics$estimate[3]);writeLines(html,"docs/index.html")
